import {inputAxes} from './input-frame.mjs';
import assert from 'node:assert/strict';
import {canStealBall} from './ball-steal.mjs';
import {browserSlidePlayerOverlap} from './native-slide-player-overlap.mjs';
import {readFileSync} from 'node:fs';
import vm from 'node:vm';
const player={team:0,x:100,y:100},opponent={team:1,x:105,y:100};
const ball={owner:opponent,x:105,y:100,z:0};
assert.equal(canStealBall(player,ball,1000,0),true);
assert.equal(canStealBall(player,ball,1000,800),false,'cooldown');
assert.equal(canStealBall(player,{...ball,owner:null},1000,0),false);
assert.equal(canStealBall(player,{...ball,owner:{team:0}},1000,0),false);
assert.equal(canStealBall(player,{...ball,z:-1},1000,0),false);
assert.equal(canStealBall(player,{...ball,x:200},1000,0),false);
assert.equal(canStealBall(player,ball,1000,-Infinity),true);
const source=readFileSync(new URL('./game.js',import.meta.url),'utf8'),match=source.match(/^function press\(actor,input\) \{.*\}$/m);
assert.ok(match,'press action must exist');
const outcome=vm.runInNewContext(`(()=>{let controlled={team:0,x:100,y:100},opponent={team:1,x:105,y:100},ball={owner:opponent,x:105,y:100,z:0,vx:2,vy:1,vz:0},lastTackle=[-Infinity,-Infinity],lastTouchTeam=1,fallen=null;const simulationNow=()=>1000,ballFootTarget=()=>({x:110,y:104}),startTackleFall=p=>{fallen=p};${match[0]};press(controlled,{up:keys.has('up'),down:keys.has('down'),left:keys.has('left'),right:keys.has('right'),run:keys.has('run')});return {ball,controlled,opponent,fallen,lastTouchTeam};})()`,{inputAxes,canStealBall,browserSlidePlayerOverlap,Object,keys:new Set(),bindings:{right:'right',left:'left',up:'up',down:'down'},screenDirectionForVector:()=>2,selectedTeamIds:[0,1],selectedKits:['home','home'],rosterTeam:()=>null,nativeSlideBody:{supports:()=>true},simulationTick:0,resetAt:0});
assert.equal(outcome.ball.owner,outcome.controlled);assert.equal(outcome.fallen,outcome.opponent);assert.equal(outcome.lastTouchTeam,0);assert.equal(outcome.ball.vx,0);
const farOutcome=vm.runInNewContext(`(()=>{let controlled={team:0,x:100,y:100},opponent={team:1,x:200,y:100},ball={owner:opponent,x:105,y:100,z:0},lastTackle=[-Infinity,-Infinity],lastTouchTeam=1,fallen=null;const simulationNow=()=>1000,ballFootTarget=()=>({x:110,y:104}),startTackleFall=p=>{fallen=p};${match[0]};press(controlled,{up:keys.has('up'),down:keys.has('down'),left:keys.has('left'),right:keys.has('right'),run:keys.has('run')});return {ball,controlled,fallen};})()`,{inputAxes,canStealBall,browserSlidePlayerOverlap,Object,keys:new Set(),bindings:{right:'right',left:'left',up:'up',down:'down'},screenDirectionForVector:()=>2,selectedTeamIds:[0,1],selectedKits:['home','home'],rosterTeam:()=>null,nativeSlideBody:{supports:()=>true},simulationTick:0,resetAt:0});
assert.equal(farOutcome.ball.owner,farOutcome.controlled,'roubo provisório continua usando contato com a bola');
assert.equal(farOutcome.fallen,null,'proximidade da bola sozinha não derruba jogador distante');
const staleOutcome=vm.runInNewContext(`(()=>{let controlled={team:0,x:100,y:100,actionVisual:{nativeSlide:true}},opponent={team:1,x:105,y:100},ball={owner:opponent,x:105,y:100,z:0},lastTackle=[-Infinity,-Infinity],lastTouchTeam=1,fallen=null;const simulationNow=()=>1000,ballFootTarget=()=>({x:110,y:104}),startTackleFall=p=>{fallen=p};${match[0]};press(controlled,{up:keys.has('up'),down:keys.has('down'),left:keys.has('left'),right:keys.has('right'),run:keys.has('run')});return {fallen};})()`,{inputAxes,canStealBall,browserSlidePlayerOverlap,Object,keys:new Set(),bindings:{right:'right',left:'left',up:'up',down:'down'},screenDirectionForVector:()=>2,selectedTeamIds:[0,1],selectedKits:['home','home'],rosterTeam:()=>null,nativeSlideBody:{supports:()=>false},simulationTick:0,resetAt:0});
assert.equal(staleOutcome.fallen,null,'carrinho anterior não autoriza queda em ação não suportada');
const independence=vm.runInNewContext(`(()=>{let controlled={team:0,x:0,y:0},other={team:1,x:0,y:0},ball={owner:null},lastTackle=[-Infinity,-Infinity],lastTouchTeam=0,calls=[];const simulationNow=()=>1000,canStealBall=p=>{calls.push(p.team);return false};${match[0]};const input={up:false,down:false,left:false,right:false,run:false};press(controlled,input);press(controlled,input);press(other,input);return {calls,lastTackle};})()`,{inputAxes,screenDirectionForVector:()=>2,selectedTeamIds:[0,1],selectedKits:['home','home'],rosterTeam:()=>null,nativeSlideBody:null,simulationTick:0,resetAt:0});
assert.deepEqual([...independence.calls],[0,1],'intervalo de carrinho é independente para cada equipe');
assert.deepEqual([...independence.lastTackle],[1000,1000]);
function pressDuringRestart(now){
 return vm.runInNewContext(`(()=>{let actor={team:0},opponent={team:1},ball={owner:opponent},lastTackle=[-Infinity,-Infinity],lastTouchTeam=1,calls=0;const simulationNow=()=>now,canStealBall=()=>{calls++;return false};${match[0]};press(actor,{up:false,down:false,left:false,right:false,run:false});return {calls,lastTackle,owner:ball.owner};})()`,{now,resetAt:1000,inputAxes,screenDirectionForVector:()=>2,selectedTeamIds:[0,1],selectedKits:['home','home'],rosterTeam:()=>null,nativeSlideBody:null,simulationTick:0});
}
assert.equal(pressDuringRestart(999).calls,0,'restart blocks tackle until the action lock expires');
assert.equal(pressDuringRestart(1000).calls,1,'tackle becomes available when the action lock expires');
console.log('OK: roubo próximo, adversário, bola no chão e intervalo');
